:root {
  --bg: #111111;
  --bg-soft: #171717;
  --surface: #1f1f1f;
  --text: #f5f5f5;
  --muted: #b8b8b8;
  --accent: #e63946;
  --accent-dark: #b71f2d;
  --border: #2b2b2b;
  --success: #3ddc97;
  --warning: #ffbf69;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }

.container {
  width: min(1180px, 92%);
  margin: 0 auto;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--accent);
  color: #fff;
  padding: .5rem .8rem;
  z-index: 999;
}
.skip-link:focus { left: .5rem; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(17,17,17,.92);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(8px);
}
.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
  gap: 1rem;
}
.brand {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  letter-spacing: .08em;
  font-size: 1.5rem;
  text-transform: uppercase;
}
.brand span { color: var(--accent); }

.nav-toggle {
  display: none;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  padding: .45rem .6rem;
  border-radius: .4rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.1rem;
}
.nav-links a {
  color: var(--muted);
  font-size: .95rem;
}
.nav-links a.active,
.nav-links a:hover,
.nav-links a:focus-visible { color: #fff; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: .72rem 1.15rem;
  border-radius: .45rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .03em;
  border: 1px solid transparent;
  transition: background .2s ease, transform .2s ease, border-color .2s ease;
}
.btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-1px); }
.btn-outline {
  border-color: var(--accent);
  color: var(--text);
}
.btn-outline:hover { background: rgba(230,57,70,.15); }

.hero {
  padding: 5.5rem 0 4.5rem;
}
.kicker {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: .09em;
  font-size: .82rem;
  font-weight: 700;
}
h1, h2, h3 {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  text-transform: uppercase;
  letter-spacing: .03em;
  line-height: 1.1;
  margin: .35rem 0 1rem;
}
h1 { font-size: clamp(2rem, 5vw, 4rem); }
h2 { font-size: clamp(1.7rem, 4vw, 2.8rem); }
h3 { font-size: clamp(1.3rem, 2.6vw, 1.8rem); }

.section {
  padding: 4.4rem 0;
}
.section-dark { background: var(--bg-soft); }
.grid {
  display: grid;
  gap: 1.25rem;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 2rem;
  align-items: center;
}

.carousel {
  position: relative;
  overflow: hidden;
  border-radius: .8rem;
  border: 1px solid var(--border);
  min-height: 360px;
}
.carousel-track {
  display: flex;
  transition: transform .45s ease;
  will-change: transform;
}
.carousel-slide {
  min-width: 100%;
  position: relative;
}
.carousel-slide img {
  width: 100%;
  height: 460px;
  object-fit: cover;
  filter: saturate(1.05) contrast(1.05);
}
.slide-caption {
  position: absolute;
  inset: auto 0 0 0;
  padding: 1rem;
  background: linear-gradient(transparent, rgba(0,0,0,.75));
  font-weight: 600;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: rgba(17,17,17,.84);
  color: #fff;
  cursor: pointer;
}
.carousel-btn:hover { background: rgba(230,57,70,.9); }
.carousel-btn.prev { left: .7rem; }
.carousel-btn.next { right: .7rem; }

.cards-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 1rem;
}
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  padding: 1.1rem;
  border-radius: .7rem;
}

.cta-banner {
  padding: 2.2rem;
  background: linear-gradient(135deg, #2a0f12 0%, #4f1218 38%, #6f1b23 100%);
  border-radius: .8rem;
  border: 1px solid rgba(255,255,255,.12);
  text-align: center;
}
.cta-banner p { color: #f5d8db; }

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: .6rem;
}
table {
  width: 100%;
  border-collapse: collapse;
  min-width: 650px;
}
th, td {
  padding: .9rem .8rem;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
th {
  background: #191919;
  text-transform: uppercase;
  letter-spacing: .03em;
  font-size: .82rem;
}
tr:hover td { background: #1a1a1a; }

.toggle-wrap {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}
.toggle-btn {
  min-height: 44px;
  min-width: 130px;
  border: none;
  background: transparent;
  color: var(--muted);
  padding: .6rem 1rem;
  cursor: pointer;
  text-transform: uppercase;
  font-weight: 700;
}
.toggle-btn.active { background: var(--accent); color: #fff; }

.instructor-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
}
select {
  min-height: 44px;
  background: #171717;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: .4rem;
  padding: .55rem .7rem;
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 1rem;
}
.instructor-card {
  border: 1px solid var(--border);
  border-radius: .7rem;
  overflow: hidden;
  background: var(--surface);
}
.instructor-card img {
  width: 100%;
  height: 260px;
  object-fit: cover;
}
.instructor-card .content { padding: .9rem; }
.badge {
  display: inline-block;
  padding: .25rem .5rem;
  border-radius: 999px;
  font-size: .72rem;
  background: rgba(230,57,70,.15);
  color: #ffadb3;
}

.faq-item {
  border: 1px solid var(--border);
  border-radius: .6rem;
  margin-bottom: .75rem;
  background: var(--surface);
}
.faq-btn {
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--text);
  font-weight: 700;
  min-height: 52px;
  padding: .85rem 1rem;
  cursor: pointer;
}
.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease;
  padding: 0 1rem;
  color: var(--muted);
}
.faq-item.open .faq-content {
  max-height: 240px;
  padding-bottom: .95rem;
}

.newsletter {
  display: grid;
  gap: .8rem;
  max-width: 520px;
}
.newsletter label { font-weight: 600; }
.newsletter input {
  min-height: 46px;
  border-radius: .45rem;
  border: 1px solid var(--border);
  background: #161616;
  color: #fff;
  padding: .7rem .8rem;
}
.input-error { border-color: var(--accent) !important; }
.form-msg { font-size: .92rem; }
.form-msg.error { color: #ff99a1; }
.form-msg.success { color: var(--success); }

footer {
  border-top: 1px solid var(--border);
  padding: 2rem 0 2.5rem;
  margin-top: 3rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: 1rem;
}
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: .9rem;
  color: var(--muted);
}

@media (max-width: 980px) {
